/* From Uiverse.io by rricol - Tags: email, input */
.__UIV_SCOPE__ .input {
  position: relative;
  max-width: 190px;
  border: none;
  box-shadow: 0px 1.5px 0px 0px #858585;
  padding: .5rem;
  transition: all 200ms ease-in-out;
  opacity: .8;
}

.__UIV_SCOPE__ .input-box {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .input-label {
  font-size: .625rem;
  font-weight: bold;
  color: #858585;
  margin-bottom: 4px;
  margin-left: 1px;
}

.__UIV_SCOPE__ .input-helper {
  color: #858585;
  font-size: .5rem;
  margin-top: 6px;
  margin-left: 1px;
  visibility: hidden;
  transform: translateY(-.5rem);
  transition: all 100ms linear;
  z-index: -1;
}

.__UIV_SCOPE__ .input::placeholder {
  color: rgb(145, 145, 145);
  font-size: .75rem;
}

.__UIV_SCOPE__ .input::after {
  content: attr(placeholder);
  position: absolute;
  color: #161616;
  top: 0;
  left: 0;
}

.__UIV_SCOPE__ .input:focus {
  border: none;
  box-shadow: 0px 1.5px 0px 0px #72E985;
  outline: none;
}

.__UIV_SCOPE__ .input:focus + .input-helper {
  visibility: visible;
  transform: translateY(0rem);
}

.__UIV_SCOPE__ .input:focus::placeholder {
  visibility: hidden;
}
